/*
 * @file  init_clock.c
 * @brief Mikroe clock initialization for Nordic Semiconductor NRF54L MCUs.
 *        Generated by scripts/nordic_mcus.py - do not edit, change the generator instead.
 *
 * SystemInit:
 *   1. Nordic MDK SystemInit (system_nrf54l.c, unmodified): errata workarounds and trims.
 *   2. Clock setup from the NECTO clock configuration (VALUE_* macros in core_header.h),
 *      in this order:
 *        a) CPU frequency (OSCILLATORS_PLL_FREQ: 128 or 64 MHz)
 *        b) HFXO started when CLOCK_TASKS_XOSTART is set
 *        c) LFCLK.SRC written and LFCLK started when CLOCK_TASKS_LFCLKSTART is set
 */

#include "core_header.h"
#include "mcu.h"

/* The MDK SystemInit is compiled here under another name and called from the MikroE SystemInit below. */
/* The CPU frequency is set below from OSCILLATORS_PLL_FREQ instead of the MDK default. */
#define NRF_SKIP_CLOCK_CONFIGURATION
/* The core always starts in the secure state, but NECTO does not build with -mcmse: without this the MDK
 * skips its secure-only setup (errata 37, APPROTECT/TAMPC, KMU). The value 1 (not 3) keeps the SAU
 * "all non-secure" setup in system_config_sau.h disabled, as in a normal secure build. */
#ifndef __ARM_FEATURE_CMSE
#define __ARM_FEATURE_CMSE 1
#endif
#define SystemInit nordic_mdk_system_init
#include "system_nrf54l.c"
#undef SystemInit

void SystemInit( void )
{
    nordic_mdk_system_init();

    /* CPU clock: PLL at 128 MHz or 64 MHz. */
    NRF_OSCILLATORS_S->PLL.FREQ = VALUE_OSCILLATORS_PLL_FREQ;

    if ( VALUE_CLOCK_TASKS_XOSTART & 1 ) {
        /* Start the high frequency crystal oscillator and wait until it runs. */
        NRF_CLOCK_S->EVENTS_XOSTARTED = 0;
        NRF_CLOCK_S->TASKS_XOSTART = 1;
        while ( 0 == NRF_CLOCK_S->EVENTS_XOSTARTED );
        NRF_CLOCK_S->EVENTS_XOSTARTED = 0;
    }

    /* Select the LFCLK source, start LFCLK and wait until it runs. */
    if ( VALUE_CLOCK_TASKS_LFCLKSTART & 1 ) {
        NRF_CLOCK_S->LFCLK.SRC = VALUE_CLOCK_LFCLK_SRC;
        NRF_CLOCK_S->EVENTS_LFCLKSTARTED = 0;
        NRF_CLOCK_S->TASKS_LFCLKSTART = 1;
        while ( 0 == NRF_CLOCK_S->EVENTS_LFCLKSTARTED );
        NRF_CLOCK_S->EVENTS_LFCLKSTARTED = 0;
    }

    SystemCoreClockUpdate();
}
